draw((-2,3)--(2,1));
real f(real x) { return .5*x^2-1.5x+2;}
draw(graph(f,2,4));

label("$f(x)$",(-3,5),E);

dot("$(-4,0)$", (-4,0), NW);
dot("$(-3,2)$", (-3,2), NW);
dot("$(-2,3)$", (-2,3), N);
dot("$(0,2)$", (0,2), NE);
dot("$(2,1)$", (2,1), S);
dot("$(3,2)$", (3,2), SE);
dot("$(4,4)$", (4,4), NE);
dot((3.56, 3), red);

